import itertools
def cells_info(inp,line,outs):
    H,W=len(inp),len(inp[0])
    hl=[r for r in range(H) if all(v==line for v in inp[r])]
    vl=[c for c in range(W) if all(inp[r][c]==line for r in range(H))]
    def segs(n,lines):
        s=[];p=0
        for L in lines+[n]:
            if L>p: s.append((p,L)); 
            p=L+1
        return s
    rs,cs=segs(H,hl),segs(W,vl)
    six=[(r,c) for r in range(H) for c in range(W) if inp[r][c]==6]
